applyPathRoute=function(){
  const p=location.pathname.replace(/\/+$/,"");
  if(activeSubject!=="tu101"){
    if(p.endsWith("/flashcards")){ensureFlashcardWorkspace();switchTab("flashcards");renderFlashcards();return}
    return coreApplyPathRoute();
  }
  if(p.endsWith("/flashcards")){ensureFlashcardWorkspace();switchTab("flashcards");renderFlashcards();return}
  if(p.endsWith("/summary")){switchTab("summary");renderTu101Summary();if(location.hash)setTimeout(function(){const el=document.querySelector(location.hash);if(el)el.scrollIntoView({block:"start"})},80);return}
  if(p.endsWith("/quiz")){tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);switchTab("quiz");renderTu101QuizLayer();return}
  if(p.endsWith("/notes")){switchTab("notes");renderNotesHub();return}
  if(p.endsWith("/history")){switchTab("history");renderHistory();return}
  if(p.endsWith("/prompt")){switchTab("prompt");return}
  if(p.endsWith("/settings")){switchTab("settings");applyPrefsEverywhere();return}
  switchTab("tracker");renderTracker();
};

