const TU101_L1_PARTS={"tu1-foundations":{"label":"Part 1 • Big Picture & Indigenous Foundations","source":"Professor Lecture 1 slide (primary)","summaries":["tu1s1","tu1s2"],"topics":["Southeast Asia: diversity, identity, and why ASEAN matters","Indigenous society, rice cultivation, settlement, and animism"]},"tu1-influences":{"label":"Part 2 • Cultural Layers & Adaptation","source":"Professor Lecture 1 slide (primary)","summaries":["tu1s3"],"topics":["Indianization, Sinicization, Islamization, and Westernization","Multi-ethnicity, language families, and hybrid culture"]},"tu1-language":{"label":"Part 3 • Ethnicity, Migration & Language Families","source":"Professor Lecture 1 slide (primary)","summaries":["tu1s4","tu1s5"],"topics":["Multi-ethnicity, language families, and hybrid culture"]},"tu1-kinship":{"label":"Part 4 • Hybrid Culture, Kinship & Conflict","source":"Professor Lecture 1 slide (primary)","summaries":["tu1s6","tu1s7"],"topics":["Multi-ethnicity, language families, and hybrid culture","Cultural kinship, shared culture, and national cultural conflict","Southeast Asia: diversity, identity, and why ASEAN matters"]},"tu1-all":{"label":"Cumulative • TU101 Lecture 1","source":"Professor Lecture 1 slide (primary) + assigned readings for support","summaries":["tu1s1","tu1s2","tu1s3","tu1s4","tu1s5","tu1s6","tu1s7"],"topics":null,"cumulative":true}};

const TU101_L1_VISUALS={"tu1s1":"<figure class=\"tu101-study-visual\" aria-label=\"Southeast Asia diversity and connection memory diagram\"><svg viewBox=\"0 0 900 270\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"226\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"v-title\">SOUTHEAST ASIA = DIVERSE + CONNECTED</text><g class=\"v-chip\"><rect x=\"70\" y=\"90\" width=\"180\" height=\"54\" rx=\"14\"/><text x=\"160\" y=\"123\" text-anchor=\"middle\">Languages • Ethnicities</text><rect x=\"70\" y=\"162\" width=\"180\" height=\"54\" rx=\"14\"/><text x=\"160\" y=\"195\" text-anchor=\"middle\">Religions • Beliefs</text></g><g class=\"v-arrow\"><path d=\"M270 117 C350 117 350 105 420 105\"/><path d=\"M270 189 C350 189 350 165 420 165\"/></g><circle cx=\"505\" cy=\"135\" r=\"70\" class=\"v-core\"/><text x=\"505\" y=\"128\" text-anchor=\"middle\" class=\"v-core-text\">REGIONAL</text><text x=\"505\" y=\"151\" text-anchor=\"middle\" class=\"v-core-text\">CONNECTION</text><g class=\"v-arrow\"><path d=\"M578 112 C650 90 680 90 748 96\"/><path d=\"M578 160 C650 185 680 185 748 178\"/></g><g class=\"v-chip\"><rect x=\"650\" y=\"70\" width=\"180\" height=\"54\" rx=\"14\"/><text x=\"740\" y=\"103\" text-anchor=\"middle\">Trade • Migration</text><rect x=\"650\" y=\"150\" width=\"180\" height=\"54\" rx=\"14\"/><text x=\"740\" y=\"183\" text-anchor=\"middle\">Food • Shared culture</text></g></svg><figcaption>Visual memory map • Professor-slide idea: diversity and connection exist at the same time.</figcaption></figure>","tu1s2":"<figure class=\"tu101-study-visual\" aria-label=\"Rice waterways stilt houses and spirit beliefs diagram\"><svg viewBox=\"0 0 900 300\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"252\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"56\" text-anchor=\"middle\" class=\"v-title\">INDIGENOUS FOUNDATIONS</text><path d=\"M40 215 Q160 180 285 215 T530 215 T860 215 L860 258 L40 258Z\" class=\"v-water\"/><g class=\"v-house\"><path d=\"M315 152 L410 92 L505 152Z\"/><rect x=\"338\" y=\"152\" width=\"144\" height=\"62\" rx=\"4\"/><line x1=\"355\" y1=\"214\" x2=\"355\" y2=\"254\"/><line x1=\"465\" y1=\"214\" x2=\"465\" y2=\"254\"/></g><g class=\"v-label\"><text x=\"120\" y=\"105\">🌾 Rice cultivation</text><text x=\"120\" y=\"132\">→ settled communities</text><text x=\"315\" y=\"284\">River / canal + stilt house = flood adaptation</text><text x=\"590\" y=\"104\">🌿 Animism</text><text x=\"590\" y=\"132\">spirits in nature</text><text x=\"590\" y=\"164\">🏮 Nats • City Pillars</text><text x=\"590\" y=\"194\">ancestor / guardian shrines</text></g></svg><figcaption>Visual study aid • Rice, waterways, raised houses and spirit beliefs are connected parts of the lecture.</figcaption></figure>","tu1s3":"<figure class=\"tu101-study-visual\" aria-label=\"Four cultural influence layers diagram\"><svg viewBox=\"0 0 900 300\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"252\" rx=\"24\" class=\"v-bg\"/><circle cx=\"450\" cy=\"150\" r=\"72\" class=\"v-core\"/><text x=\"450\" y=\"143\" text-anchor=\"middle\" class=\"v-core-text\">LOCAL</text><text x=\"450\" y=\"166\" text-anchor=\"middle\" class=\"v-core-text\">SOCIETIES</text><g class=\"v-arrow\"><path d=\"M255 82 L377 122\"/><path d=\"M645 82 L523 122\"/><path d=\"M255 220 L377 178\"/><path d=\"M645 220 L523 178\"/></g><g class=\"v-chip\"><rect x=\"70\" y=\"52\" width=\"190\" height=\"62\" rx=\"15\"/><text x=\"165\" y=\"81\" text-anchor=\"middle\">INDIANIZATION</text><text x=\"165\" y=\"101\" text-anchor=\"middle\">trade • temples • epics</text><rect x=\"640\" y=\"52\" width=\"190\" height=\"62\" rx=\"15\"/><text x=\"735\" y=\"81\" text-anchor=\"middle\">SINICIZATION</text><text x=\"735\" y=\"101\" text-anchor=\"middle\">trade • migration</text><rect x=\"70\" y=\"194\" width=\"190\" height=\"62\" rx=\"15\"/><text x=\"165\" y=\"223\" text-anchor=\"middle\">ISLAMIZATION</text><text x=\"165\" y=\"243\" text-anchor=\"middle\">13th c. • trade • Sufis</text><rect x=\"640\" y=\"194\" width=\"190\" height=\"62\" rx=\"15\"/><text x=\"735\" y=\"223\" text-anchor=\"middle\">WESTERNIZATION</text><text x=\"735\" y=\"243\" text-anchor=\"middle\">colonial legacies</text></g><text x=\"450\" y=\"267\" text-anchor=\"middle\" class=\"v-note\">Outside influence → local adaptation → layered hybrid culture</text></svg><figcaption>Visual memory map • I–S–I–W. The key process is adaptation, not simple replacement.</figcaption></figure>","tu1s4":"<figure class=\"tu101-study-visual\" aria-label=\"Cross-border ethnicity and migration diagram\"><svg viewBox=\"0 0 900 280\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"232\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"v-title\">CULTURAL MAP ≠ POLITICAL MAP</text><g class=\"v-border\"><line x1=\"300\" y1=\"82\" x2=\"300\" y2=\"224\"/><line x1=\"600\" y1=\"82\" x2=\"600\" y2=\"224\"/></g><text x=\"155\" y=\"104\" text-anchor=\"middle\" class=\"v-country\">COUNTRY A</text><text x=\"450\" y=\"104\" text-anchor=\"middle\" class=\"v-country\">COUNTRY B</text><text x=\"745\" y=\"104\" text-anchor=\"middle\" class=\"v-country\">COUNTRY C</text><path d=\"M135 164 C290 118 470 206 730 148\" class=\"v-migrate\"/><circle cx=\"175\" cy=\"155\" r=\"16\" class=\"v-dot\"/><circle cx=\"450\" cy=\"165\" r=\"16\" class=\"v-dot\"/><circle cx=\"720\" cy=\"150\" r=\"16\" class=\"v-dot\"/><text x=\"450\" y=\"208\" text-anchor=\"middle\" class=\"v-note\">Example: Cham communities across Cambodia • Thailand • Vietnam</text><text x=\"450\" y=\"234\" text-anchor=\"middle\" class=\"v-note\">Migration • settlement • intermarriage • shifting influence</text></svg><figcaption>Visual study aid • Ethnic and language communities can cross modern state borders.</figcaption></figure>","tu1s5":"<figure class=\"tu101-study-visual\" aria-label=\"Five Southeast Asian language families memory chart\"><svg viewBox=\"0 0 900 300\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"252\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"v-title\">5 LANGUAGE FAMILIES — AA • AN • TK • TB • HM</text><g class=\"v-lang\"><rect x=\"55\" y=\"92\" width=\"150\" height=\"128\" rx=\"16\"/><text x=\"130\" y=\"122\" text-anchor=\"middle\">AA</text><text x=\"130\" y=\"150\" text-anchor=\"middle\">Austroasiatic</text><text x=\"130\" y=\"178\" text-anchor=\"middle\">Vietnamese</text><text x=\"130\" y=\"199\" text-anchor=\"middle\">Khmer • Mon</text><rect x=\"218\" y=\"92\" width=\"150\" height=\"128\" rx=\"16\"/><text x=\"293\" y=\"122\" text-anchor=\"middle\">AN</text><text x=\"293\" y=\"150\" text-anchor=\"middle\">Austronesian</text><text x=\"293\" y=\"178\" text-anchor=\"middle\">Island /</text><text x=\"293\" y=\"199\" text-anchor=\"middle\">archipelagic belt</text><rect x=\"381\" y=\"92\" width=\"150\" height=\"128\" rx=\"16\"/><text x=\"456\" y=\"122\" text-anchor=\"middle\">TK</text><text x=\"456\" y=\"150\" text-anchor=\"middle\">Tai-Kadai</text><text x=\"456\" y=\"185\" text-anchor=\"middle\">Thai • Lao</text><rect x=\"544\" y=\"92\" width=\"150\" height=\"128\" rx=\"16\"/><text x=\"619\" y=\"122\" text-anchor=\"middle\">TB</text><text x=\"619\" y=\"150\" text-anchor=\"middle\">Tibeto-Burman</text><text x=\"619\" y=\"185\" text-anchor=\"middle\">Burmese</text><rect x=\"707\" y=\"92\" width=\"138\" height=\"128\" rx=\"16\"/><text x=\"776\" y=\"122\" text-anchor=\"middle\">HM</text><text x=\"776\" y=\"150\" text-anchor=\"middle\">Hmong-Mien</text><text x=\"776\" y=\"185\" text-anchor=\"middle\">Highlands</text></g><text x=\"450\" y=\"250\" text-anchor=\"middle\" class=\"v-note\">Memorize the anchors first; then connect each family to its geography.</text></svg><figcaption>Visual memory chart • The five families and their fastest exam anchors.</figcaption></figure>","tu1s6":"<figure class=\"tu101-study-visual\" aria-label=\"Hybrid culture and glocalization diagram\"><svg viewBox=\"0 0 900 300\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"252\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"v-title\">HYBRID CULTURE</text><circle cx=\"315\" cy=\"146\" r=\"90\" class=\"v-local\"/><circle cx=\"455\" cy=\"146\" r=\"90\" class=\"v-outside\"/><text x=\"270\" y=\"142\" text-anchor=\"middle\" class=\"v-core-text\">LOCAL</text><text x=\"270\" y=\"166\" text-anchor=\"middle\" class=\"v-core-text\">CULTURE</text><text x=\"500\" y=\"142\" text-anchor=\"middle\" class=\"v-core-text\">OUTSIDE</text><text x=\"500\" y=\"166\" text-anchor=\"middle\" class=\"v-core-text\">INFLUENCE</text><text x=\"385\" y=\"137\" text-anchor=\"middle\" class=\"v-overlap\">HYBRID</text><text x=\"385\" y=\"160\" text-anchor=\"middle\" class=\"v-overlap\">IDENTITY</text><g class=\"v-label\"><text x=\"675\" y=\"108\">Peranakan • Baba/Nyonya</text><text x=\"675\" y=\"140\">Baba Malay = creole</text><text x=\"675\" y=\"172\">Sino-Portuguese architecture</text><text x=\"675\" y=\"204\">Glocalization = global + local</text></g><text x=\"450\" y=\"267\" text-anchor=\"middle\" class=\"v-note\">Malacca • Singapore • Bangkok Chinatown</text></svg><figcaption>Visual study aid • Hybrid culture is adaptation that creates a new local form, not a 50/50 formula.</figcaption></figure>","tu1s7":"<figure class=\"tu101-study-visual\" aria-label=\"Cultural kinship and national cultural conflict diagram\"><svg viewBox=\"0 0 900 310\" role=\"img\" aria-hidden=\"true\"><rect x=\"18\" y=\"22\" width=\"864\" height=\"262\" rx=\"24\" class=\"v-bg\"/><text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"v-title\">SHARED ROOTS → LOCAL VERSIONS → NATIONAL CLAIMS?</text><rect x=\"320\" y=\"82\" width=\"260\" height=\"56\" rx=\"16\" class=\"v-core\"/><text x=\"450\" y=\"116\" text-anchor=\"middle\" class=\"v-core-text\">PRE-NATIONAL SHARED CULTURE</text><g class=\"v-arrow\"><path d=\"M390 140 L230 188\"/><path d=\"M450 140 L450 188\"/><path d=\"M510 140 L670 188\"/></g><g class=\"v-chip\"><rect x=\"100\" y=\"188\" width=\"220\" height=\"56\" rx=\"15\"/><text x=\"210\" y=\"221\" text-anchor=\"middle\">Local version A</text><rect x=\"340\" y=\"188\" width=\"220\" height=\"56\" rx=\"15\"/><text x=\"450\" y=\"221\" text-anchor=\"middle\">Local version B</text><rect x=\"580\" y=\"188\" width=\"220\" height=\"56\" rx=\"15\"/><text x=\"690\" y=\"221\" text-anchor=\"middle\">Local version C</text></g><text x=\"450\" y=\"270\" text-anchor=\"middle\" class=\"v-note\">Batik • keris • wayang • food • palaces • drums → “same same, but different”</text></svg><figcaption>Visual memory map • Cultural kinship recognizes shared roots without erasing local differences.</figcaption></figure>"};
function tu101VisualMarkup(id){return TU101_L1_VISUALS[id]||""}

const TU101_L1_FLASHCARD_BANK={"title":"TU101 Lecture 1 Flashcards","bankVersion":"tu101-l1-v1","parts":[{"id":"tu1-l1-foundations-v1","label":"Part 1 • Big Picture & Indigenous Foundations","description":"Diversity + connection, rice, waterways, food and belief.","cards":[{"id":"asean-society","front":"What does “ASEAN society” mean in Lecture 1?","back":"The wider socio-cultural landscape of Southeast Asia, not only ASEAN as an organization. ไทยช่วยจำ: สังคมและวัฒนธรรมของภูมิภาคที่เชื่อมข้ามพรมแดน"},{"id":"diverse-connected","front":"What is the lecture’s big-picture formula for Southeast Asia?","back":"Diverse but connected. Differences coexist with long histories of migration, trade and shared culture. ไทยช่วยจำ: หลากหลายแต่เชื่อมโยงกัน"},{"id":"mosaic","front":"Why does the professor call the region a mosaic of peoples?","back":"Because many histories, ethnicities, languages, religions, beliefs and norms developed together over time. ไทยช่วยจำ: หลายกลุ่ม หลายภาษา หลายความเชื่อ"},{"id":"rice","front":"Why is rice cultivation important?","back":"It helped transform local societies toward more settled agricultural communities; the slide links it to southern China. ไทยช่วยจำ: ข้าว → ตั้งถิ่นฐาน"},{"id":"waterways","front":"Where did many early communities develop?","back":"Along rivers and canals. ไทยช่วยจำ: ชุมชนผูกกับทางน้ำ"},{"id":"stilt","front":"Why are stilt or pile houses important?","back":"They are a regional adaptation that helps protect homes from flooding and water conditions. ไทยช่วยจำ: บ้านยกพื้น = รับมือน้ำ"},{"id":"animism","front":"What is animism?","back":"Belief that spirits inhabit natural objects and phenomena such as mountains, rivers, land, trees, animals and plants. ไทยช่วยจำ: วิญญาณอยู่ในธรรมชาติ"},{"id":"guardians","front":"Give key guardian-spirit examples from the slide.","back":"Thailand/Cambodia City Pillars, Myanmar Nats and Vietnamese village shrines. ไทยช่วยจำ: หลักเมือง • Nats • ศาลหมู่บ้าน"},{"id":"datok","front":"What does Datok Kong illustrate?","back":"Local guardian-spirit belief among Chinese communities in Malaysia, Singapore and Indonesia—an example of cultural adaptation. ไทยช่วยจำ: จีน + ความเชื่อท้องถิ่น"},{"id":"fermented","front":"What do shrimp paste and fermented-food examples show?","back":"A shared regional food pattern expressed under different local names and forms. ไทยช่วยจำ: รูปแบบร่วม แต่ชื่อ/รสท้องถิ่นต่างกัน"}]},{"id":"tu1-l1-influences-v1","label":"Part 2 • Cultural Layers & Adaptation","description":"Indianization, Sinicization, Islamization and Westernization.","cards":[{"id":"indianization","front":"What is Indianization in this lecture?","back":"Indian cultural influence carried largely through Indian Ocean trade, including Hindu-Buddhist kingdoms, temples, architecture and epics. ไทยช่วยจำ: อินเดียผ่านการค้า + ศาสนา/วัด"},{"id":"epics","front":"Which two Indian epics are named in the slide?","back":"Ramayana and Mahabharata. ไทยช่วยจำ: รามายณะ + มหาภารตะ"},{"id":"sinicization","front":"What is Sinicization?","back":"Non-Chinese societies coming under Chinese cultural and social influence through trade, migration and political interaction. ไทยช่วยจำ: อิทธิพลจีนต่อสังคมที่ไม่ใช่จีน"},{"id":"islamization","front":"When and how does the slide emphasize Islamization?","back":"From around the 13th century, especially through trade and Sufi networks. ไทยช่วยจำ: ศตวรรษ 13 • การค้า • Sufi"},{"id":"westernization","front":"What lasting Western colonial legacies does the slide list?","back":"Architecture, education, language, cuisine and clothing, along with social-structure changes. ไทยช่วยจำ: สถาปัตย์ • การศึกษา • ภาษา • อาหาร • เสื้อผ้า"},{"id":"adaptation","front":"What is the key rule for understanding outside cultural influence?","back":"Adaptation, not simple replacement: outside influences are localized and mixed with existing beliefs. ไทยช่วยจำ: รับมาแล้วปรับ ไม่ใช่ลบของเดิม"},{"id":"buddhism","front":"How does the lecture describe Buddhism in Southeast Asia?","back":"Not an unchanged copy; it can intertwine with animism and spirit worship. ไทยช่วยจำ: พุทธ + ความเชื่อผี/วิญญาณ"},{"id":"religion-layering","front":"Can Christianity or Islam coexist with older local practices?","back":"Yes. The slide notes coexistence with spirit belief and ancestor veneration. ไทยช่วยจำ: ศาสนาใหม่อยู่ร่วมกับความเชื่อเดิมได้"},{"id":"crossroads","front":"Why is Southeast Asia called a cultural crossroads?","back":"Multiple civilizations and outside influences met local societies, producing layered hybridity. ไทยช่วยจำ: หลายอิทธิพลมาพบและผสมกัน"},{"id":"isiw","front":"What does the memory code I–S–I–W stand for?","back":"Indianization • Sinicization • Islamization • Westernization. ไทยช่วยจำ: 4 ชั้นอิทธิพลภายนอก"}]},{"id":"tu1-l1-language-v1","label":"Part 3 • Ethnicity, Migration & Language Families","description":"Cross-border societies and the five language-family anchors.","cards":[{"id":"multiethnic","front":"What is a multi-ethnic society?","back":"A society where different ethnic groups coexist with their own social organization, culture, beliefs and identities. ไทยช่วยจำ: หลายชาติพันธุ์อยู่ร่วมกัน"},{"id":"500groups","front":"How ethnically diverse is Southeast Asia in the slide?","back":"The lecture describes more than 500 ethnic groups across the region. ไทยช่วยจำ: มากกว่า 500 กลุ่ม"},{"id":"intermarriage","front":"What helps create multicultural societies?","back":"Migration, outsider settlements and interethnic marriage. ไทยช่วยจำ: ย้ายถิ่น + ตั้งชุมชน + แต่งงานข้ามกลุ่ม"},{"id":"cham","front":"Why are the Cham important in the lecture?","back":"They show that one ethnic/language community can live across Cambodia, Thailand and Vietnam. ไทยช่วยจำ: ชุมชนข้ามพรมแดน"},{"id":"fivefamilies","front":"Name the five language families in the lecture.","back":"Austroasiatic, Austronesian, Tai-Kadai, Tibeto-Burman and Hmong-Mien. ไทยช่วยจำ: AA • AN • TK • TB • HM"},{"id":"aa","front":"What is the fastest anchor for Austroasiatic?","back":"Vietnamese, Khmer and Mon; mainly a mainland anchor. ไทยช่วยจำ: เวียดนาม • เขมร • มอญ"},{"id":"an","front":"What is the fastest anchor for Austronesian?","back":"The island/archipelagic belt—Malaysia, Indonesia, Brunei and the Philippines. ไทยช่วยจำ: หมู่เกาะ"},{"id":"tk","front":"What is the fastest anchor for Tai-Kadai?","back":"Thai, Lao and related Tai groups. ไทยช่วยจำ: ไทย • ลาว"},{"id":"tb","front":"What is the fastest anchor for Tibeto-Burman?","back":"Burmese, the official language of Myanmar. ไทยช่วยจำ: ภาษาพม่า"},{"id":"hm","front":"What is the fastest anchor for Hmong-Mien?","back":"Highland peoples extending from southern China across Myanmar, Thailand, Laos and Vietnam. ไทยช่วยจำ: กลุ่มพื้นที่สูง"}]},{"id":"tu1-l1-hybrid-v1","label":"Part 4 • Hybrid Culture, Kinship & Conflict","description":"Peranakan, glocalization, shared roots and national claims.","cards":[{"id":"hybrid","front":"What is hybrid culture?","back":"A new cultural pattern created when local culture blends with outside influences. ไทยช่วยจำ: ท้องถิ่น + ภายนอก → รูปแบบใหม่"},{"id":"peranakan","front":"Who are the Peranakan in the lecture?","back":"Chinese / Straits-born Chinese hybrid communities associated with southern Thailand, the Malay archipelago, Singapore, Malaysia and Indonesia. ไทยช่วยจำ: ชุมชนจีนลูกผสมในโลกมลายู"},{"id":"baba-nyonya","front":"What do Baba and Nyonya mean?","back":"Baba = men; Nyonya = women in Peranakan terminology. ไทยช่วยจำ: Baba ชาย • Nyonya หญิง"},{"id":"baba-malay","front":"Why is Baba Malay a hybrid example?","back":"It is a creole language blending Malay and Hokkien. ไทยช่วยจำ: ภาษาใหม่จาก Malay + Hokkien"},{"id":"sinoportuguese","front":"What does Sino-Portuguese architecture demonstrate?","back":"Visible architectural hybridity combining cultural influences. ไทยช่วยจำ: สถาปัตยกรรมลูกผสม"},{"id":"glocalization","front":"What is glocalization?","back":"Globalization + local identities. ไทยช่วยจำ: global + local"},{"id":"glocal-cases","front":"Name the three glocalization/hybridity cases highlighted in the slide.","back":"Malacca, Singapore and Bangkok’s Chinatown. ไทยช่วยจำ: มะละกา • สิงคโปร์ • เยาวราช/Chinatown กรุงเทพฯ"},{"id":"conflict","front":"How can shared culture create cultural conflict?","back":"Modern states may claim exclusive ownership of traditions that have older shared regional roots. ไทยช่วยจำ: ของร่วมเก่า → รัฐใหม่อ้างเป็นของตน"},{"id":"shared-examples","front":"Give examples of shared/contested culture from the slide.","back":"Batik, keris/kris, wayang kulit, Rasa Sayang, Tor-tor and shared national-food debates. ไทยช่วยจำ: batik • keris • wayang • อาหาร"},{"id":"gordang","front":"What are Gordang Sambilan and Sibaso?","back":"Gordang Sambilan are nine sacred drums; Sibaso is the medium/shaman linked to summoning ancestral spirits. ไทยช่วยจำ: กลอง 9 ใบ + คนทรง"},{"id":"kinship","front":"What is cultural kinship?","back":"Recognition that societies share historical cultural roots while still developing different local versions. ไทยช่วยจำ: รากร่วม แต่รูปแบบท้องถิ่นต่างกัน"},{"id":"same-different","front":"What does “same same [or/but] different” mean?","back":"Shared roots do not make cultures identical; local adaptations and meanings still matter. ไทยช่วยจำ: คล้ายกันเพราะรากร่วม แต่ไม่เหมือนกันทั้งหมด"}]}]};
window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};
window.D_STUDY_FLASHCARD_BANKS.tu101=TU101_L1_FLASHCARD_BANK;

let tuQuizMode="review",tuQuizPart="tu1-foundations",tuQuizSession=null;

function tuQuizBank(mode,part){
  const bank=mode==="mastery"?TU101_L1_MASTERY:TU101_L1_REVIEW;
  if(part==="tu1-all")return ["tu1-foundations","tu1-influences","tu1-language","tu1-kinship"].flatMap(function(id){return bank[id]||[]});
  return bank[part]||[];
}
function tuQuizDraftKey(mode,part){return activeUser?"d-study-tu101-draft::"+activeUser.id+"::"+TU101_L1_BANK_VERSION+"::"+part+"::"+mode:""}
function tuFreshQuizSession(mode,part){
  const quiz=tuQuizBank(mode,part);
  return{mode:mode,part:part,answers:Array(quiz.length).fill(null),confidence:Array(quiz.length).fill("confident"),optionOrders:makeOptionOrders(quiz),current:0,submitted:false};
}
function tuLoadQuizDraft(mode,part){
  const quiz=tuQuizBank(mode,part);
  try{
    const d=JSON.parse(localStorage.getItem(tuQuizDraftKey(mode,part))||"null");
    if(d&&Array.isArray(d.answers)&&d.answers.length===quiz.length&&!d.submitted){
      d.mode=mode;d.part=part;
      d.confidence=Array.isArray(d.confidence)&&d.confidence.length===quiz.length?d.confidence:Array(quiz.length).fill("confident");
      d.optionOrders=Array.isArray(d.optionOrders)&&d.optionOrders.length===quiz.length?d.optionOrders:makeOptionOrders(quiz);
      return d;
    }
  }catch(_){}
  return tuFreshQuizSession(mode,part);
}
function tuSaveQuizDraft(){
  if(activeUser&&tuQuizSession&&!tuQuizSession.submitted)localStorage.setItem(tuQuizDraftKey(tuQuizMode,tuQuizPart),JSON.stringify(tuQuizSession));
}
function tuClearQuizDraft(mode,part){if(activeUser)localStorage.removeItem(tuQuizDraftKey(mode,part))}
function tuQuizAttempts(part,mode){
  return (state&&state.quizHistory||[]).filter(function(h){return h.bankVersion===TU101_L1_BANK_VERSION&&h.partId===part&&(h.mode||"review")===(mode||tuQuizMode)});
}
function tuQuizStatus(part,mode){
  const xs=tuQuizAttempts(part,mode);if(!xs.length)return{cls:"not-started",label:"Not started"};
  const h=xs[0],learn=Number(h.adjustedPercent??h.percent??0);
  if(Number(h.guessed||0)>0)return{cls:"red",label:"Completed with guessed answers"};
  if(learn<60)return{cls:"orange",label:"Needs more work"};
  if(Number(h.unsure||0)>0||learn<80)return{cls:"yellow",label:"Practiced"};
  return{cls:"green",label:"Strong attempt"};
}
function tuQuizAttemptSummary(part,mode){
  const xs=tuQuizAttempts(part,mode),name=mode==="review"?"Reviewing":"Mastering";
  if(!xs.length)return name+" not started • no completed attempts yet";
  const best=Math.max.apply(null,xs.map(function(h){return Number(h.adjustedPercent??h.percent??0)})),last=xs[0];
  return (xs.length===1?"Taken 1 time":"Taken "+xs.length+" times")+" • Best "+best+"% • Last "+(last.date||"—");
}
function tuSetQuizPart(part){
  if(!TU101_L1_PARTS[part])return;
  tuSaveQuizDraft();tuQuizPart=part;tuQuizSession=tuLoadQuizDraft(tuQuizMode,part);renderTu101QuizLayer();
}
function tuSetQuizMode(mode){
  if(!["review","mastery"].includes(mode))return;
  tuSaveQuizDraft();tuQuizMode=mode;tuQuizSession=tuLoadQuizDraft(mode,tuQuizPart);renderTu101QuizLayer();
}
function tuQuestionNote(q,part){return state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[questionNoteKey(q,part)]||""}
function tuSectionNote(part){return state.quizNotes&&state.quizNotes.sections&&state.quizNotes.sections[part]||""}
function tuSaveSectionNote(value,part){state.quizNotes.sections[part]=value;persist()}
function tuSaveQuestionNote(q,value,part){state.quizNotes.questions[questionNoteKey(q,part)]=value;persist()}
function tuRenderQuizPicker(layer){
  const ids=Object.keys(TU101_L1_PARTS);
  const regular=ids.filter(function(id){return id!=="tu1-all"});
  const completed=regular.filter(function(id){return (state.quizHistory||[]).some(function(h){return h.bankVersion===TU101_L1_BANK_VERSION&&h.partId===id})}).length;
  layer.querySelector("#tuLectureQuizProgress").textContent=completed+"/"+regular.length+" done";
  const root=layer.querySelector("#tuPartPicker");
  root.innerHTML=ids.map(function(id){
    const m=TU101_L1_PARTS[id],r=tuQuizStatus(id,"review"),mm=tuQuizStatus(id,"mastery"),attempts=(state.quizHistory||[]).filter(function(h){return h.bankVersion===TU101_L1_BANK_VERSION&&h.partId===id}).length;
    return '<button class="part-btn '+(id===tuQuizPart?"active":"")+'" data-tu-part="'+id+'"><span class="practice-status-cluster"><span class="practice-mode-status" title="Reviewing: '+esc(r.label)+'">R <i class="practice-dot '+r.cls+'"></i></span><span class="practice-mode-status" title="Mastering: '+esc(mm.label)+'">M <i class="practice-dot '+mm.cls+'"></i></span></span><b>'+esc(m.label)+'</b><span class="small">'+(id==="tu1-all"?"40 questions":"10 questions")+' • '+(attempts?("Taken "+attempts+" time"+(attempts===1?"":"s")):"Not taken yet")+'</span></button>';
  }).join("");
  root.querySelectorAll("[data-tu-part]").forEach(function(b){b.onclick=function(){tuSetQuizPart(b.dataset.tuPart)}});
}
function tuRenderReadingGuide(layer){
  const meta=TU101_L1_PARTS[tuQuizPart],root=layer.querySelector("#tuQuizReadingGuide");
  root.innerHTML='<b>📖 Read alongside this quiz:</b><ul>'+meta.summaries.map(function(id){
    const x=TU101_L1_SUMMARY.find(function(s){return s.id===id});
    return '<li><a class="summary-link" href="'+APP_BASE+'/tu101/summary/#summary-'+id+'">'+esc(x?(x.titleEn||x.title||id):id)+' →</a></li>';
  }).join("")+'</ul>';
}
function tuRenderQuizQuestion(layer){
  const quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=TU101_L1_PARTS[tuQuizPart],rn=layer.querySelector("#tuResumeNotice"),area=layer.querySelector("#tuQuizArea");
  if(!tuQuizSession||tuQuizSession.mode!==tuQuizMode||tuQuizSession.part!==tuQuizPart)tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);
  if(tuQuizSession.submitted){tuRenderQuizResult(layer);return}
  const answered=tuQuizSession.answers.filter(function(x){return x!==null}).length;
  rn.innerHTML=answered>0?'<div class="notice" style="margin-bottom:12px"><b>Autosaved '+(tuQuizMode==="review"?"Reviewing":"Mastering")+' draft.</b> '+answered+'/'+quiz.length+' answers saved for '+esc(activeUser.username)+' in '+esc(meta.label)+'.</div>':"";
  if(!quiz.length){area.innerHTML='<div class="notice">No questions are mapped to this part yet.</div>';return}
  const i=Math.max(0,Math.min(tuQuizSession.current,quiz.length-1));tuQuizSession.current=i;
  const item=quiz[i],conf=tuQuizSession.confidence[i]||"confident",order=tuQuizSession.optionOrders[i]||[0,1,2,3];
  area.innerHTML='<div class="quiz-top"><div><b>'+(tuQuizMode==="review"?"Reviewing":"Mastering")+' • '+esc(meta.label)+'</b><div class="small">'+esc(meta.source)+' • '+answered+'/'+quiz.length+' answered</div><div class="quiz-attempt-detail">'+esc(tuQuizAttemptSummary(tuQuizPart,tuQuizMode))+'</div></div><button class="secondary" id="tuClearAttempt">Clear this attempt</button></div>'+
    '<div class="quiz-progress"><div style="width:'+Math.round((i+1)/quiz.length*100)+'%"></div></div>'+
    '<div class="number-grid">'+quiz.map(function(q,n){return '<div class="qnum '+(tuQuizSession.answers[n]!==null?"answered ":"")+(n===i?"current ":"")+(tuQuestionNote(q,tuQuizPart)?"noted":"")+'" data-tu-n="'+n+'">'+(n+1)+'</div>'}).join("")+'</div>'+
    '<div class="question-note-legend"><i class="saved-note-dot"></i> saved note</div>'+
    '<div class="qmeta"><div class="qmeta-left"><span class="tag">'+(tuQuizMode==="review"?"Reviewing":"Mastering")+'</span><span class="small">Question '+(i+1)+' of '+quiz.length+'</span></div><button class="secondary topic-hint-btn" id="tuTopicHintBtn" type="button" aria-expanded="false">💡 Hint</button></div>'+
    '<div class="topic-hint-reveal" id="tuTopicHintReveal" hidden><span class="topic-hint-label">Topic</span><b>'+esc(item.topic)+'</b><span class="small">This only shows the source topic — not the answer.</span></div>'+
    '<div class="quiz-notes-row"><div class="quiz-note-box"><div class="quiz-note-head"><b>📝 Notes for this section</b><span>Autosaved • '+esc(meta.label)+'</span></div><textarea id="tuSectionQuizNote" placeholder="Key idea, source detail, trap, something to revisit…">'+esc(tuSectionNote(tuQuizPart))+'</textarea>'+noteMediaBoxMarkup("section",tuQuizPart)+'</div></div>'+
    '<div class="question">'+esc(item.q)+'</div>'+
    order.map(function(orig,display){return '<label class="option '+(tuQuizSession.answers[i]===orig?"selected":"")+'"><input type="radio" name="tu-a" value="'+orig+'" '+(tuQuizSession.answers[i]===orig?"checked":"")+'> '+String.fromCharCode(65+display)+'. '+esc(item.opts[orig])+'</label>'}).join("")+
    '<div class="quiz-note-box question-note"><div class="quiz-note-head"><b>✏️ Note for Question '+(i+1)+'</b><span>Autosaved to this question</span></div><textarea id="tuQuestionQuizNote" placeholder="Why I chose this, what confused me, professor wording…">'+esc(tuQuestionNote(item,tuQuizPart))+'</textarea>'+noteMediaBoxMarkup("question",questionNoteKey(item,tuQuizPart))+'</div>'+
    '<div class="confidence-wrap"><b>Confidence check</b><div class="small">Leave both unselected if confident. Mark one if the answer may be a fluke.</div><div class="confidence-actions"><button class="confidence-btn '+(conf==="unsure"?"active":"")+'" data-tu-conf="unsure">□ Not sure</button><button class="confidence-btn guess '+(conf==="guessed"?"active":"")+'" data-tu-conf="guessed">□ Guessed</button></div></div>'+
    '<div class="qnav"><button class="secondary" id="tuPrev" '+(i===0?"disabled":"")+'>← Previous</button>'+(i<quiz.length-1?'<button id="tuNext">Next →</button>':'<button id="tuSubmit" '+(answered<quiz.length?"disabled":"")+'>Submit Quiz</button>')+'</div>'+
    (i===quiz.length-1&&answered<quiz.length?'<div class="notice" style="margin-top:12px">Answer all questions before Submit — '+(quiz.length-answered)+' left.</div>':"");
  const hint=area.querySelector("#tuTopicHintBtn"),reveal=area.querySelector("#tuTopicHintReveal");if(hint&&reveal)hint.onclick=function(){const on=reveal.hidden;reveal.hidden=!on;hint.classList.toggle("active",on);hint.setAttribute("aria-expanded",String(on));hint.innerHTML=on?"💡 Topic shown":"💡 Hint"};
  const sn=area.querySelector("#tuSectionQuizNote");if(sn){sn.oninput=function(e){tuSaveSectionNote(e.target.value,tuQuizPart)};bindRichNoteEditor(sn,"section",tuQuizPart)}
  const qn=area.querySelector("#tuQuestionQuizNote");if(qn){qn.oninput=function(e){tuSaveQuestionNote(item,e.target.value,tuQuizPart)};bindRichNoteEditor(qn,"question",questionNoteKey(item,tuQuizPart))}
  area.querySelectorAll('input[name="tu-a"]').forEach(function(r){r.onchange=function(e){tuQuizSession.answers[i]=Number(e.target.value);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
  area.querySelectorAll("[data-tu-conf]").forEach(function(b){b.onclick=function(){const v=b.dataset.tuConf;tuQuizSession.confidence[i]=tuQuizSession.confidence[i]===v?"confident":v;tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
  area.querySelectorAll("[data-tu-n]").forEach(function(n){n.onclick=function(){tuQuizSession.current=Number(n.dataset.tuN);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
  const prev=area.querySelector("#tuPrev"),next=area.querySelector("#tuNext"),submit=area.querySelector("#tuSubmit"),clear=area.querySelector("#tuClearAttempt");
  if(prev)prev.onclick=function(){tuQuizSession.current--;tuSaveQuizDraft();tuRenderQuizQuestion(layer)};
  if(next)next.onclick=function(){tuQuizSession.current++;tuSaveQuizDraft();tuRenderQuizQuestion(layer)};
  if(submit)submit.onclick=function(){tuSubmitQuiz(layer)};
  if(clear)clear.onclick=function(){if(confirm("Clear answers for "+meta.label+" ("+tuQuizMode+")?")){tuQuizSession=tuFreshQuizSession(tuQuizMode,tuQuizPart);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}};
}
function tuSubmitQuiz(layer){
  const quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=TU101_L1_PARTS[tuQuizPart];
  if(tuQuizSession.answers.some(function(x){return x===null})){alert("Please answer all questions.");return}
  const date=new Date().toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"});
  let correct=0,weighted=0,guessed=0,unsure=0;const by={};
  quiz.forEach(function(item,i){
    const ok=tuQuizSession.answers[i]===item.ans,conf=tuQuizSession.confidence[i]||"confident",w=ok?confidenceWeight(conf):0;
    if(ok)correct++;weighted+=w;if(conf==="guessed")guessed++;if(conf==="unsure")unsure++;
    if(!by[item.topic])by[item.topic]={c:0,t:0,w:0,guess:0,unsure:0,allConfidentCorrect:true};
    const b=by[item.topic];b.t++;if(ok)b.c++;b.w+=w;if(conf==="guessed")b.guess++;if(conf==="unsure")b.unsure++;if(!ok||conf!=="confident")b.allConfidentCorrect=false;
  });
  Object.entries(by).forEach(function(entry){
    const topic=entry[0],v=entry[1],raw=Math.round(v.c/v.t*100),adj=Math.round(v.w/v.t*100),idx=state.topics.findIndex(function(t){return t.topic===topic}),old=state.quizTopicStats[topic]||{attempts:0,bestAdjusted:0,masteryPasses:0};
    let masteryPasses=old.masteryPasses||0;if(tuQuizMode==="mastery"&&v.allConfidentCorrect)masteryPasses++;
    if(idx>=0){
      state.accuracy[idx]=adj;state.lastReview[idx]=date;const prev=state.topics[idx].status;
      if(adj<60)state.topics[idx].status="Learning";
      else if(adj<80)state.topics[idx].status="Learned · Not Reviewed";
      else if(tuQuizMode==="mastery"&&masteryPasses>=2&&(prev==="Reviewed & Practiced"||prev==="Mastered"))state.topics[idx].status="Mastered";
      else state.topics[idx].status="Reviewed & Practiced";
    }
    state.quizTopicStats[topic]={attempts:(old.attempts||0)+1,bestAdjusted:Math.max(old.bestAdjusted||0,adj),latestAdjusted:adj,latestRaw:raw,last:date,mode:tuQuizMode,part:tuQuizPart,guessed:v.guess,unsure:v.unsure,masteryPasses:masteryPasses};
  });
  const rawPct=Math.round(correct/quiz.length*100),adjPct=Math.round(weighted/quiz.length*100);
  state.quizHistory.unshift({name:meta.label,pages:"TU101 Lecture 1",bankVersion:TU101_L1_BANK_VERSION,partId:tuQuizPart,mode:tuQuizMode,date:date,score:correct,total:quiz.length,percent:rawPct,adjustedPercent:adjPct,guessed:guessed,unsure:unsure,answers:tuQuizSession.answers.slice(),confidence:tuQuizSession.confidence.slice(),optionOrders:tuQuizSession.optionOrders.map(function(x){return x.slice()}),questionSnapshot:quiz.map(function(item){return{q:item.q,opts:item.opts.slice(),ans:item.ans,topic:item.topic,why:item.why}})});
  state.quizHistory=state.quizHistory.slice(0,50);persist();appendDevActivity("Quiz submitted",meta.label+" • "+tuQuizMode+" • raw "+rawPct+"% • learning "+adjPct+"%",activeUser);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuQuizSession.submitted=true;renderTracker();renderHistory();renderNotesHub();renderTu101QuizLayer();
}
function tuRenderQuizResult(layer){
  const quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=TU101_L1_PARTS[tuQuizPart],area=layer.querySelector("#tuQuizArea");
  const h=(state.quizHistory||[]).find(function(x){return x.bankVersion===TU101_L1_BANK_VERSION&&x.partId===tuQuizPart&&(x.mode||"review")===tuQuizMode});
  if(!h){tuQuizSession.submitted=false;tuRenderQuizQuestion(layer);return}
  const topicRows=[...new Set(quiz.map(function(x){return x.topic}))].map(function(topic){
    const st=state.quizTopicStats[topic],idx=state.topics.findIndex(function(t){return t.topic===topic});
    return '<div class="topic-score"><b>'+esc(topic)+'</b><span>'+(st&&st.latestRaw!=null?st.latestRaw:"—")+'% raw</span><span>'+(st&&st.latestAdjusted!=null?st.latestAdjusted:"—")+'% learn</span><span class="small">'+(idx>=0?esc(state.topics[idx].status):"—")+'</span></div>';
  }).join("");
  area.innerHTML='<div class="result-head"><div class="result-box"><span class="small">Raw score</span><b>'+h.score+'/'+h.total+'</b></div><div class="result-box"><span class="small">Raw accuracy</span><b>'+h.percent+'%</b></div><div class="result-box"><span class="small">Learning score</span><b>'+h.adjustedPercent+'%</b></div><div class="result-box"><span class="small">Flagged</span><b>'+((h.guessed||0)+(h.unsure||0))+'</b><span class="small">'+(h.guessed||0)+' guessed • '+(h.unsure||0)+' unsure</span></div></div>'+
    '<div class="notice"><b>'+esc(meta.label)+'</b><br>Correct + confident = full evidence, correct + Not sure = 70%, correct + Guessed = 40%, wrong = 0. Reviewing does not award Mastered.</div>'+
    '<div class="card" style="box-shadow:none;margin-top:14px"><div class="lecture-title">Topic results</div>'+topicRows+'</div>'+
    '<div class="card" style="box-shadow:none;margin-top:14px"><div class="lecture-title">Review answers</div>'+quiz.map(function(item,i){
      const chosen=h.answers[i],ok=chosen===item.ans,conf=h.confidence&&h.confidence[i]||"confident",order=h.optionOrders&&h.optionOrders[i]||[0,1,2,3],chosenPos=order.indexOf(chosen),correctPos=order.indexOf(item.ans);
      return '<div class="review-item"><div><b>'+(i+1)+'. '+esc(item.q)+'</b> <span class="tag">'+esc(item.topic)+'</span> <span class="tag">'+(conf==="guessed"?"Guessed":conf==="unsure"?"Not sure":"Confident")+'</span></div><div class="'+(ok?"correct":"wrong")+'" style="padding:8px 10px;border-radius:9px;margin-top:8px">Your answer: '+String.fromCharCode(65+Math.max(0,chosenPos))+'. '+esc(item.opts[chosen])+' '+(ok?"✓":"✗")+'</div>'+(ok?"":'<div class="correct" style="padding:8px 10px;border-radius:9px;margin-top:6px">Correct: '+String.fromCharCode(65+Math.max(0,correctPos))+'. '+esc(item.opts[item.ans])+'</div>')+'<div class="explain">'+esc(item.why)+(ok&&conf!=="confident"?" <b>Correct but flagged, so it receives less mastery weight.</b>":"")+'</div>'+(tuQuestionNote(item,tuQuizPart)?'<div class="note-review"><b>Your saved note:</b><div>'+esc(tuQuestionNote(item,tuQuizPart)).replace(/\n/g,"<br>")+'</div></div>':"")+'</div>';
    }).join("")+'</div>'+
    '<div class="qnav"><a class="button secondary" href="'+APP_BASE+'/tu101/summary/#summary-'+meta.summaries[0]+'">Read Summary</a><button id="tuRetake">Retake this part</button></div>';
  const retake=area.querySelector("#tuRetake");if(retake)retake.onclick=function(){tuQuizSession=tuFreshQuizSession(tuQuizMode,tuQuizPart);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuSaveQuizDraft();renderTu101QuizLayer()};
}
renderTu101QuizLayer=function(){
  let layer=document.getElementById("tu101QuizLayer");if(!layer){layer=document.createElement("div");layer.id="tu101QuizLayer";document.getElementById("quiz").appendChild(layer)}
  if(!TU101_L1_PARTS[tuQuizPart])tuQuizPart="tu1-foundations";
  if(!tuQuizSession||tuQuizSession.part!==tuQuizPart||tuQuizSession.mode!==tuQuizMode)tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);
  layer.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Practice</div><h2>TU101 Quiz Library</h2><p>Lecture 1 uses the same Reviewing → Mastering workflow as EC214. Questions are primarily grounded in the professor slide; assigned readings are supporting context.</p></div></div>'+
    '<div class="card quiz-shell"><div class="quiz-library"><div class="lecture-title">✅ TU101 Quiz Library</div><div class="small">Lecture 1 • 4 focused parts + 40-question cumulative. Reviewing and Mastering each contain 40 English, slide-first questions aligned to the expanded bilingual summary.</div><ul class="library-list quiz-library-list"><li class="quiz-library-item current"><a class="library-link active" href="'+APP_BASE+'/tu101/quiz/">Lecture 1 — Understanding Southeast Asia • Diversity, Identity & Why ASEAN Matter →</a><span class="quiz-set-progress" id="tuLectureQuizProgress">0/4 done</span></li><li class="quiz-library-item"><span class="library-link preview-locked-link">Lectures 2–6 — quiz banks not built yet</span></li></ul></div>'+
    '<div id="tuPartPicker" class="part-picker"></div>'+
    '<div class="practice-dot-legend"><span><i class="practice-dot not-started"></i> not started</span><span><i class="practice-dot red"></i> guessed</span><span><i class="practice-dot orange"></i> needs work</span><span><i class="practice-dot yellow"></i> practiced</span><span><i class="practice-dot green"></i> strong</span><span style="margin-left:auto">R = Reviewing • M = Mastering</span></div>'+
    '<div class="mode-switch"><button class="mode-btn '+(tuQuizMode==="review"?"active":"")+'" data-tu-mode="review"><b>Reviewing — recommended first</b><span class="small">Clearer recall + application • does not award Mastered</span></button><button class="mode-btn '+(tuQuizMode==="mastery"?"active":"")+'" data-tu-mode="mastery"><b>Mastering — harder</b><span class="small">Close distractors • source comparison • multi-step reasoning</span></button></div>'+
    '<div id="tuQuizReadingGuide" class="read-with"></div><div id="tuResumeNotice"></div><div id="tuQuizArea"></div></div>';
  layer.querySelectorAll("[data-tu-mode]").forEach(function(b){b.onclick=function(){tuSetQuizMode(b.dataset.tuMode)}});
  tuRenderQuizPicker(layer);tuRenderReadingGuide(layer);tuRenderQuizQuestion(layer);
};

renderTu101Summary=function(){
  let layer=document.getElementById("tu101SummaryLayer");if(!layer){layer=document.createElement("div");layer.id="tu101SummaryLayer";document.getElementById("summary").appendChild(layer)}
  layer.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Study Notes</div><h2>TU101 Lecture 1 — English exam wording + Thai learning support</h2><p>The topic language and Understand-it language are independent. Professor slide content remains the primary source.</p></div></div>'+
    '<div class="summary-search-card tu101-summary-search"><div class="summary-search-head"><div><div class="lecture-title">🔎 Search Lecture 1</div><div class="small" id="tu101SearchMeta">Searches English + Thai study notes</div></div><div class="summary-search-input-row"><input id="tu101SummarySearch" type="search" placeholder="Search animism, Datok Kong, Austronesian, Peranakan, Gordang Sambilan…"><button type="button" class="secondary" id="tu101SummaryClear">Clear</button></div></div><div class="summary-search-results" id="tu101SummaryResults"></div></div>'+
    '<div class="summary-library"><div class="lecture-title">📝 Lecture 1 / Chapter 1 — Complete Slide-first Study Sheet</div><div class="small">Use the top-right Topic Language buttons for the notes. Open Understand it and choose its language separately.</div><div class="tu101-scope-banner"><b>Source priority:</b> Professor Morragotwong’s “Understanding Southeast Asia: Diversity, Identity, and Why ASEAN Matter” slide is the coverage backbone. The visual study aids below rebuild the slide concepts into compact diagrams for memorization.</div></div>'+
    TU101_L1_SUMMARY.map(function(x,i){return '<article class="slide-card tu101-summary-card tu101-l1-card" id="summary-'+x.id+'" data-tu-topic-lang="en" data-tu-understand-lang="en"><div class="tu101-card-top"><div><div class="slide-no">Lecture 1 • Section '+(i+1)+' of '+TU101_L1_SUMMARY.length+'</div><div class="small tu101-lang-label">Topic language</div></div><div class="tu101-card-lang-toggle"><button type="button" class="secondary active" data-tu-topic-lang-btn="en">English</button><button type="button" class="secondary" data-tu-topic-lang-btn="th">ไทย</button></div></div><h2 data-tu-topic-copy="en">'+x.titleEn+'</h2><h2 data-tu-topic-copy="th" hidden>'+x.titleTh+'</h2><div class="tu101-memory-hook" data-tu-topic-copy="en">'+x.memoryEn+'</div><div class="tu101-memory-hook" data-tu-topic-copy="th" hidden>'+x.memoryTh+'</div>'+tu101VisualMarkup(x.id)+'<ul data-tu-topic-copy="en">'+x.bullets.map(function(p){return"<li>"+p.en+"</li>"}).join("")+'</ul><ul data-tu-topic-copy="th" hidden>'+x.bullets.map(function(p){return"<li>"+p.th+"</li>"}).join("")+'</ul><div class="summary-deep-dive"><button type="button" class="deep-dive-toggle" aria-expanded="false"><span class="deep-dive-icon">💡</span><span><b>Understand it / เข้าใจแบบง่าย</b><small>Independent language control inside</small></span><span class="deep-dive-cue">Expand ▾</span></button><div class="deep-dive-expanded" hidden><div class="tu101-understand-head"><span class="small"><b>Understand-it language</b></span><div class="tu101-understand-lang-toggle"><button type="button" class="secondary active" data-tu-understand-lang-btn="en">English</button><button type="button" class="secondary" data-tu-understand-lang-btn="th">ไทย</button></div></div><div class="deep-dive-body"><p data-tu-understand-copy="en">'+x.understandEn+'</p><p data-tu-understand-copy="th" hidden>'+x.understandTh+'</p></div></div></div></article>'}).join("")+
    '<div class="card tu101-next-summary"><div class="lecture-title">Exam strategy</div><p class="small"><b>Understand difficult ideas in Thai → keep the topic card in English → memorize the memory hook → use the English quiz and flashcards for active recall.</b></p></div>';
  layer.querySelectorAll(".deep-dive-toggle").forEach(function(b){b.onclick=function(){const box=b.nextElementSibling,on=box.hidden;box.hidden=!on;b.setAttribute("aria-expanded",String(on));const cue=b.querySelector(".deep-dive-cue");if(cue)cue.textContent=on?"Collapse ▴":"Expand ▾"}});
  layer.querySelectorAll("[data-tu-topic-lang-btn]").forEach(function(b){b.onclick=function(){const card=b.closest(".tu101-l1-card"),lang=b.dataset.tuTopicLangBtn;card.dataset.tuTopicLang=lang;card.querySelectorAll("[data-tu-topic-lang-btn]").forEach(function(x){x.classList.toggle("active",x.dataset.tuTopicLangBtn===lang)});card.querySelectorAll("[data-tu-topic-copy]").forEach(function(x){x.hidden=x.dataset.tuTopicCopy!==lang})}});
  layer.querySelectorAll("[data-tu-understand-lang-btn]").forEach(function(b){b.onclick=function(){const card=b.closest(".tu101-l1-card"),lang=b.dataset.tuUnderstandLangBtn;card.dataset.tuUnderstandLang=lang;card.querySelectorAll("[data-tu-understand-lang-btn]").forEach(function(x){x.classList.toggle("active",x.dataset.tuUnderstandLangBtn===lang)});card.querySelectorAll("[data-tu-understand-copy]").forEach(function(x){x.hidden=x.dataset.tuUnderstandCopy!==lang})}});
  const input=layer.querySelector("#tu101SummarySearch"),results=layer.querySelector("#tu101SummaryResults"),meta=layer.querySelector("#tu101SearchMeta");
  function clearMarks(){layer.querySelectorAll("mark.tu101-search-mark").forEach(function(m){m.replaceWith(document.createTextNode(m.textContent))})}
  function run(){const raw=(input.value||"").trim(),query=raw.toLowerCase();clearMarks();if(!query){results.innerHTML='<div class="summary-search-empty">Search any Lecture 1 concept, example, English term, or Thai explanation.</div>';meta.textContent="Searches English + Thai study notes";return}const terms=query.split(/\s+/).filter(Boolean),hits=TU101_L1_SUMMARY.filter(function(x){const all=[x.titleEn,x.titleTh,x.memoryEn,x.memoryTh,x.understandEn,x.understandTh].concat(x.bullets.flatMap(function(p){return[p.en,p.th]})).join(" ").replace(/<[^>]+>/g,"").toLowerCase();return terms.every(function(t){return all.includes(t)})});meta.textContent=hits.length+" result"+(hits.length===1?"":"s");results.innerHTML=hits.length?hits.map(function(x){return '<button class="summary-search-result" type="button" data-tu-summary="'+x.id+'"><span class="summary-search-source">Lecture 1</span><b>'+x.titleEn+'</b><span>'+esc(x.memoryEn)+'</span></button>'}).join(""):'<div class="summary-search-empty">No Lecture 1 summary context matched “'+esc(raw)+'”.</div>';results.querySelectorAll("[data-tu-summary]").forEach(function(b){b.onclick=function(){const card=layer.querySelector("#summary-"+b.dataset.tuSummary);card&&card.scrollIntoView({behavior:"smooth",block:"center"})}})}
  input.oninput=run;layer.querySelector("#tu101SummaryClear").onclick=function(){input.value="";run()};run();
};

const v1310CoreGetAllSavedNotes=getAllSavedNotes;
getAllSavedNotes=function(){
  if(activeSubject!=="tu101"){
    const base=v1310CoreGetAllSavedNotes();
    if(activeSubject!=="ec214")return base;
    const items=(Array.isArray(base)?base:[]).filter(function(item){return !String(item&&item.key||"").startsWith("flashcard::ec214::")});
    const flashSeen=new Set();
    normalizedFlashcardDecks("ec214").filter(function(deck){return!deck.cumulative}).forEach(function(deck){
      deck.cards.forEach(function(card){
        if(flashSeen.has(card.id))return;flashSeen.add(card.id);
        const key=flashcardNoteKey("ec214",card.id),val=state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[key];
        if(!String(val||"").trim()&&!getNoteMedia("question",key).length)return;
        items.push({kind:"question",lecture:deck.lectureLabel||"EC214",title:card.front,meta:deck.label+" • Flashcard • Answer: "+card.back,value:String(val||""),key:key,sort:5});
      });
    });
    return items;
  }
  const items=[];
  Object.entries(state.notes||{}).forEach(function(entry){
    const idx=entry[0],val=entry[1],media=getNoteMedia("progress",idx);if(!String(val||"").trim()&&!media.length)return;
    const t=state.topics[Number(idx)];items.push({kind:"progress",lecture:t&&t.lecture||"Other",title:t&&t.topic||("Progress topic #"+idx),meta:"Progress topic note",value:String(val),key:String(idx),sort:1});
  });
  Object.entries(state.quizNotes&&state.quizNotes.sections||{}).forEach(function(entry){
    const part=entry[0],val=entry[1];if(!String(val||"").trim()&&!getNoteMedia("section",part).length)return;
    const m=TU101_L1_PARTS[part];items.push({kind:"section",lecture:m?"Lecture 1":"Other",title:m?m.label:part,meta:(m?m.source+" • ":"")+"Quiz section note",value:String(val),key:part,sort:2});
  });
  const known=new Set();
  Object.keys(TU101_L1_PARTS).forEach(function(part){["review","mastery"].forEach(function(mode){tuQuizBank(mode,part).forEach(function(item){
    const key=questionNoteKey(item,part),val=state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[key];
    if((!String(val||"").trim()&&!getNoteMedia("question",key).length)||known.has(key))return;known.add(key);
    items.push({kind:"question",lecture:"Lecture 1",title:item.q,meta:TU101_L1_PARTS[part].label+" • "+(mode==="review"?"Reviewing":"Mastering")+" • "+item.topic,value:String(val),key:key,partId:part,question:item,sort:3});
  })})});
  Object.entries(state.quizNotes&&state.quizNotes.questions||{}).forEach(function(entry){const key=entry[0],val=entry[1];if(String(key).startsWith("flashcard::"))return;if((!String(val||"").trim()&&!getNoteMedia("question",key).length)||known.has(key))return;items.push({kind:"question-orphan",lecture:"Lecture 1",title:"Saved quiz question note",meta:"Archived TU101 question",value:String(val),key:key,sort:4})});
  const flashSeen=new Set();
  normalizedFlashcardDecks("tu101").filter(function(deck){return!deck.cumulative}).forEach(function(deck){
    deck.cards.forEach(function(card){
      if(flashSeen.has(card.id))return;flashSeen.add(card.id);
      const key=flashcardNoteKey("tu101",card.id),val=state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[key];
      if(!String(val||"").trim()&&!getNoteMedia("question",key).length)return;
      items.push({kind:"question",lecture:"Lecture 1",title:card.front,meta:deck.label+" • Flashcard • Answer: "+card.back,value:String(val||""),key:key,sort:5});
    });
  });
  return items;
};
