function ensureTuLectureLoaded(id){
 if(tuLectureData(id))return Promise.resolve(tuLectureData(id));
 if(!TU101_MODULE_URLS[id])return Promise.reject(new Error("Unknown TU101 lecture "+id));
 if(tuModulePromises[id])return tuModulePromises[id];
 tuModulePromises[id]=new Promise(function(resolve,reject){
   const script=document.createElement("script");script.src=TU101_MODULE_URLS[id];script.async=true;script.dataset.tuLectureModule=id;
   script.onload=function(){const data=tuLectureData(id);if(data){refreshTu101FlashcardBank();resolve(data)}else reject(new Error("TU101 "+id+" module loaded without data"))};
   script.onerror=function(){delete tuModulePromises[id];reject(new Error("Could not load TU101 "+id+" module"))};
   document.head.appendChild(script);
 });
 return tuModulePromises[id];
}
function ensureAllTu101ModulesLoaded(){return Promise.all(["l2","l3","l4","l5","l6"].map(ensureTuLectureLoaded)).then(function(){refreshTu101FlashcardBank();return true})}
window.addEventListener("d-study-tu101-module-loaded",function(){refreshTu101FlashcardBank()});

