  '<div class="card tu101-next-summary"><div class="lecture-title">Exam strategy</div><p class="small"><b>Understand difficult ideas in Thai → keep the key term in English → memorize the hook → use Reviewing → Mastering → Flashcards for active recall.</b></p><button type="button" id="tuSummaryOpenQuiz">Practice '+esc(data.lectureLabel)+' Quiz →</button></div>';
 layer.querySelectorAll("[data-tu-summary-lecture]").forEach(function(b){b.onclick=function(){setTuSummaryLecture(b.dataset.tuSummaryLecture)}});
