 layer.querySelectorAll("[data-tu-understand-lang-btn]").forEach(function(b){b.onclick=function(){const card=b.closest(".tu101-l1-card"),lang=b.dataset.tuUnderstandLangBtn;card.dataset.tuUnderstandLang=lang;card.querySelectorAll("[data-tu-understand-lang-btn]").forEach(function(x){x.classList.toggle("active",x.dataset.tuUnderstandLangBtn===lang)});card.querySelectorAll("[data-tu-understand-copy]").forEach(function(x){x.hidden=x.dataset.tuUnderstandCopy!==lang})}});
