 function run(){const raw=(input.value||"").trim(),query=raw.toLowerCase();clearMarks();if(!query){results.innerHTML='<div class="summary-search-empty">Search any '+esc(data.lectureLabel)+' concept, English term, or Thai explanation.</div>';meta.textContent="Searches English + Thai study notes in this lecture";return}const terms=query.split(/\s+/).filter(Boolean),hits=data.summary.filter(function(x){const all=[x.titleEn,x.titleTh,x.memoryEn,x.memoryTh,x.understandEn,x.understandTh].concat(x.bullets.flatMap(function(p){return[p.en,p.th]})).join(" ").replace(/<[^>]+>/g,"").toLowerCase();return terms.every(function(t){return all.includes(t)})});meta.textContent=hits.length+" result"+(hits.length===1?"":"s");results.innerHTML=hits.length?hits.map(function(x){return '<button class="summary-search-result" type="button" data-tu-summary="'+esc(x.id)+'"><span class="summary-search-source">'+esc(data.lectureLabel)+'</span><b>'+x.titleEn+'</b><span>'+esc(x.memoryEn)+'</span></button>'}).join(""):'<div class="summary-search-empty">No context matched “'+esc(raw)+'”.</div>';results.querySelectorAll("[data-tu-summary]").forEach(function(b){b.onclick=function(){const card=layer.querySelector("#summary-"+CSS.escape(b.dataset.tuSummary));card&&card.scrollIntoView({behavior:"smooth",block:"center"})}})}
