function tuCurrentQuizData(){return tuLectureData(tuQuizLecture)||TU101_L1_DATA}
function tuQuizBank(mode,part){
 const data=tuCurrentQuizData(),bank=mode==="mastery"?data.mastery:data.review,regular=tuLectureRegularParts(data);
 if(part===data.cumulativeId)return regular.flatMap(function(id){return bank[id]||[]});
 return bank[part]||[];
}
function tuQuizDraftKey(mode,part){const data=tuCurrentQuizData();return activeUser?"d-study-tu101-draft::"+activeUser.id+"::"+data.bankVersion+"::"+part+"::"+mode:""}
function tuFreshQuizSession(mode,part){const quiz=tuQuizBank(mode,part);return{lectureId:tuQuizLecture,mode:mode,part:part,answers:Array(quiz.length).fill(null),confidence:Array(quiz.length).fill("confident"),optionOrders:makeOptionOrders(quiz),current:0,submitted:false}}
function tuLoadQuizDraft(mode,part){const quiz=tuQuizBank(mode,part);try{const d=JSON.parse(localStorage.getItem(tuQuizDraftKey(mode,part))||"null");if(d&&Array.isArray(d.answers)&&d.answers.length===quiz.length&&!d.submitted){d.lectureId=tuQuizLecture;d.mode=mode;d.part=part;d.confidence=Array.isArray(d.confidence)&&d.confidence.length===quiz.length?d.confidence:Array(quiz.length).fill("confident");d.optionOrders=Array.isArray(d.optionOrders)&&d.optionOrders.length===quiz.length?d.optionOrders:makeOptionOrders(quiz);return d}}catch(_){}return tuFreshQuizSession(mode,part)}
function tuSaveQuizDraft(){if(activeUser&&tuQuizSession&&!tuQuizSession.submitted)localStorage.setItem(tuQuizDraftKey(tuQuizMode,tuQuizPart),JSON.stringify(tuQuizSession))}
function tuClearQuizDraft(mode,part){if(activeUser)localStorage.removeItem(tuQuizDraftKey(mode,part))}
function tuQuizAttempts(part,mode){const data=tuCurrentQuizData();return(state&&state.quizHistory||[]).filter(function(h){return h.bankVersion===data.bankVersion&&h.partId===part&&(h.mode||"review")===(mode||tuQuizMode)})}
function tuQuizStatus(part,mode){const xs=tuQuizAttempts(part,mode);if(!xs.length)return{cls:"not-started",label:"Not started"};const h=xs[0],learn=Number(h.adjustedPercent??h.percent??0);if(Number(h.guessed||0)>0)return{cls:"red",label:"Completed with guessed answers"};if(learn<60)return{cls:"orange",label:"Needs more work"};if(Number(h.unsure||0)>0||learn<80)return{cls:"yellow",label:"Practiced"};return{cls:"green",label:"Strong attempt"}}
function tuQuizAttemptSummary(part,mode){const xs=tuQuizAttempts(part,mode),name=mode==="review"?"Reviewing":"Mastering";if(!xs.length)return name+" not started • no completed attempts yet";const best=Math.max.apply(null,xs.map(function(h){return Number(h.adjustedPercent??h.percent??0)})),last=xs[0];return(xs.length===1?"Taken 1 time":"Taken "+xs.length+" times")+" • Best "+best+"% • Last "+(last.date||"—")}
async function setTuQuizLecture(id){
 if(!TU101_LECTURE_META[id])return;
 tuSaveQuizDraft();
 const layer=document.getElementById("tu101QuizLayer");if(layer)layer.innerHTML='<div class="card"><b>Loading '+esc(TU101_LECTURE_META[id].lectureLabel)+' quiz…</b><p class="small">Only this lecture module is being loaded.</p></div>';
 try{await ensureTuLectureLoaded(id);tuQuizLecture=id;const data=tuCurrentQuizData();tuQuizPart=tuLectureRegularParts(data)[0]||data.cumulativeId;tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);renderTu101QuizLayer()}catch(e){if(layer)layer.innerHTML='<div class="notice">Could not load '+esc(TU101_LECTURE_META[id].lectureLabel)+'. Refresh and try again.</div>'}
}
function tuSetQuizPart(part){const data=tuCurrentQuizData();if(!data.parts[part])return;tuSaveQuizDraft();tuQuizPart=part;tuQuizSession=tuLoadQuizDraft(tuQuizMode,part);renderTu101QuizLayer()}
function tuSetQuizMode(mode){if(!["review","mastery"].includes(mode))return;tuSaveQuizDraft();tuQuizMode=mode;tuQuizSession=tuLoadQuizDraft(mode,tuQuizPart);renderTu101QuizLayer()}
function tuQuestionNote(q,part){return state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[questionNoteKey(q,part)]||""}
function tuSectionNote(part){return state.quizNotes&&state.quizNotes.sections&&state.quizNotes.sections[part]||""}
function tuSaveSectionNote(value,part){state.quizNotes.sections[part]=value;persist()}
function tuSaveQuestionNote(q,value,part){state.quizNotes.questions[questionNoteKey(q,part)]=value;persist()}
function tuRenderQuizPicker(layer){
 const data=tuCurrentQuizData(),ids=Object.keys(data.parts),regular=tuLectureRegularParts(data),completed=regular.filter(function(id){return(state.quizHistory||[]).some(function(h){return h.bankVersion===data.bankVersion&&h.partId===id})}).length;
 layer.querySelector("#tuLectureQuizProgress").textContent=completed+"/"+regular.length+" parts done";
 const root=layer.querySelector("#tuPartPicker");
 root.innerHTML=ids.map(function(id){const m=data.parts[id],r=tuQuizStatus(id,"review"),mm=tuQuizStatus(id,"mastery"),attempts=(state.quizHistory||[]).filter(function(h){return h.bankVersion===data.bankVersion&&h.partId===id}).length,qc=tuQuizBank("review",id).length;return '<button class="part-btn '+(id===tuQuizPart?"active":"")+'" data-tu-part="'+esc(id)+'"><span class="practice-status-cluster"><span class="practice-mode-status" title="Reviewing: '+esc(r.label)+'">R <i class="practice-dot '+r.cls+'"></i></span><span class="practice-mode-status" title="Mastering: '+esc(mm.label)+'">M <i class="practice-dot '+mm.cls+'"></i></span></span><b>'+esc(m.label)+'</b><span class="small">'+qc+' questions • '+(attempts?("Taken "+attempts+" time"+(attempts===1?"":"s")):"Not taken yet")+'</span></button>'}).join("");
 root.querySelectorAll("[data-tu-part]").forEach(function(b){b.onclick=function(){tuSetQuizPart(b.dataset.tuPart)}})
}
function tuRenderReadingGuide(layer){const data=tuCurrentQuizData(),meta=data.parts[tuQuizPart],root=layer.querySelector("#tuQuizReadingGuide");root.innerHTML='<b>📖 Read alongside this quiz:</b><ul>'+meta.summaries.map(function(id){const x=data.summary.find(function(s){return s.id===id});return '<li><a class="summary-link" href="'+APP_BASE+'/tu101/summary/#summary-'+id+'" data-tu-read-summary="'+id+'">'+esc(x?(x.titleEn||x.title||id):id)+' →</a></li>'}).join("")+'</ul>';root.querySelectorAll("[data-tu-read-summary]").forEach(function(a){a.onclick=function(){tuSummaryLecture=tuQuizLecture}})}
function tuRenderQuizQuestion(layer){
 const data=tuCurrentQuizData(),quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=data.parts[tuQuizPart],rn=layer.querySelector("#tuResumeNotice"),area=layer.querySelector("#tuQuizArea");
 if(!tuQuizSession||tuQuizSession.lectureId!==tuQuizLecture||tuQuizSession.mode!==tuQuizMode||tuQuizSession.part!==tuQuizPart)tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);
 if(tuQuizSession.submitted){tuRenderQuizResult(layer);return}
 const answered=tuQuizSession.answers.filter(function(x){return x!==null}).length;
 rn.innerHTML=answered>0?'<div class="notice" style="margin-bottom:12px"><b>Autosaved '+(tuQuizMode==="review"?"Reviewing":"Mastering")+' draft.</b> '+answered+'/'+quiz.length+' answers saved for '+esc(activeUser.username)+' in '+esc(meta.label)+'.</div>':"";
 if(!quiz.length){area.innerHTML='<div class="notice">No questions are mapped to this part yet.</div>';return}
 const i=Math.max(0,Math.min(tuQuizSession.current,quiz.length-1));tuQuizSession.current=i;const item=quiz[i],conf=tuQuizSession.confidence[i]||"confident",order=tuQuizSession.optionOrders[i]||[0,1,2,3];
 area.innerHTML='<div class="quiz-top"><div><b>'+(tuQuizMode==="review"?"Reviewing":"Mastering")+' • '+esc(meta.label)+'</b><div class="small">'+esc(data.lectureLabel)+' • '+esc(meta.source)+' • '+answered+'/'+quiz.length+' answered</div><div class="quiz-attempt-detail">'+esc(tuQuizAttemptSummary(tuQuizPart,tuQuizMode))+'</div></div><button class="secondary" id="tuClearAttempt">Clear this attempt</button></div>'+
 '<div class="quiz-progress"><div style="width:'+Math.round((i+1)/quiz.length*100)+'%"></div></div>'+
 '<div class="number-grid">'+quiz.map(function(q,n){return '<div class="qnum '+(tuQuizSession.answers[n]!==null?"answered ":"")+(n===i?"current ":"")+(tuQuestionNote(q,tuQuizPart)?"noted":"")+'" data-tu-n="'+n+'">'+(n+1)+'</div>'}).join("")+'</div>'+
 '<div class="question-note-legend"><i class="saved-note-dot"></i> saved note</div>'+
 '<div class="qmeta"><div class="qmeta-left"><span class="tag">'+(tuQuizMode==="review"?"Reviewing":"Mastering")+'</span><span class="small">Question '+(i+1)+' of '+quiz.length+'</span></div><button class="secondary topic-hint-btn" id="tuTopicHintBtn" type="button" aria-expanded="false">💡 Hint</button></div>'+
 '<div class="topic-hint-reveal" id="tuTopicHintReveal" hidden><span class="topic-hint-label">Topic</span><b>'+esc(item.topic)+'</b><span class="small">This only shows the source topic — not the answer.</span></div>'+
 '<div class="quiz-notes-row"><div class="quiz-note-box"><div class="quiz-note-head"><b>📝 Notes for this section</b><span>Autosaved • '+esc(meta.label)+'</span></div><textarea id="tuSectionQuizNote" placeholder="Key idea, source detail, trap, something to revisit…">'+esc(tuSectionNote(tuQuizPart))+'</textarea>'+noteMediaBoxMarkup("section",tuQuizPart)+'</div></div>'+
 '<div class="question">'+esc(item.q)+'</div>'+
 order.map(function(orig,display){return '<label class="option '+(tuQuizSession.answers[i]===orig?"selected":"")+'"><input type="radio" name="tu-a" value="'+orig+'" '+(tuQuizSession.answers[i]===orig?"checked":"")+'> '+String.fromCharCode(65+display)+'. '+esc(item.opts[orig])+'</label>'}).join("")+
 '<div class="quiz-note-box question-note"><div class="quiz-note-head"><b>✏️ Note for Question '+(i+1)+'</b><span>Autosaved to this question</span></div><textarea id="tuQuestionQuizNote" placeholder="Why I chose this, what confused me, professor wording…">'+esc(tuQuestionNote(item,tuQuizPart))+'</textarea>'+noteMediaBoxMarkup("question",questionNoteKey(item,tuQuizPart))+'</div>'+
 '<div class="confidence-wrap"><b>Confidence check</b><div class="small">Leave both unselected if confident. Mark one if the answer may be a fluke.</div><div class="confidence-actions"><button class="confidence-btn '+(conf==="unsure"?"active":"")+'" data-tu-conf="unsure">□ Not sure</button><button class="confidence-btn guess '+(conf==="guessed"?"active":"")+'" data-tu-conf="guessed">□ Guessed</button></div></div>'+
 '<div class="qnav"><button class="secondary" id="tuPrev" '+(i===0?"disabled":"")+'>← Previous</button>'+(i<quiz.length-1?'<button id="tuNext">Next →</button>':'<button id="tuSubmit" '+(answered<quiz.length?"disabled":"")+'>Submit Quiz</button>')+'</div>'+
 (i===quiz.length-1&&answered<quiz.length?'<div class="notice" style="margin-top:12px">Answer all questions before Submit — '+(quiz.length-answered)+' left.</div>':"");
 const hint=area.querySelector("#tuTopicHintBtn"),reveal=area.querySelector("#tuTopicHintReveal");if(hint&&reveal)hint.onclick=function(){const on=reveal.hidden;reveal.hidden=!on;hint.classList.toggle("active",on);hint.setAttribute("aria-expanded",String(on));hint.innerHTML=on?"💡 Topic shown":"💡 Hint"};
 const sn=area.querySelector("#tuSectionQuizNote");if(sn){sn.oninput=function(e){tuSaveSectionNote(e.target.value,tuQuizPart)};bindRichNoteEditor(sn,"section",tuQuizPart)}
 const qn=area.querySelector("#tuQuestionQuizNote");if(qn){qn.oninput=function(e){tuSaveQuestionNote(item,e.target.value,tuQuizPart)};bindRichNoteEditor(qn,"question",questionNoteKey(item,tuQuizPart))}
 area.querySelectorAll('input[name="tu-a"]').forEach(function(r){r.onchange=function(e){tuQuizSession.answers[i]=Number(e.target.value);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
 area.querySelectorAll("[data-tu-conf]").forEach(function(b){b.onclick=function(){const v=b.dataset.tuConf;tuQuizSession.confidence[i]=tuQuizSession.confidence[i]===v?"confident":v;tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
 area.querySelectorAll("[data-tu-n]").forEach(function(n){n.onclick=function(){tuQuizSession.current=Number(n.dataset.tuN);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}});
 const prev=area.querySelector("#tuPrev"),next=area.querySelector("#tuNext"),submit=area.querySelector("#tuSubmit"),clear=area.querySelector("#tuClearAttempt");
 if(prev)prev.onclick=function(){tuQuizSession.current--;tuSaveQuizDraft();tuRenderQuizQuestion(layer)};
 if(next)next.onclick=function(){tuQuizSession.current++;tuSaveQuizDraft();tuRenderQuizQuestion(layer)};
 if(submit)submit.onclick=function(){tuSubmitQuiz(layer)};
 if(clear)clear.onclick=function(){if(confirm("Clear answers for "+meta.label+" ("+tuQuizMode+")?")){tuQuizSession=tuFreshQuizSession(tuQuizMode,tuQuizPart);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuSaveQuizDraft();tuRenderQuizQuestion(layer)}};
}
function tuSubmitQuiz(layer){
 const data=tuCurrentQuizData(),quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=data.parts[tuQuizPart];if(tuQuizSession.answers.some(function(x){return x===null})){alert("Please answer all questions.");return}
 const date=new Date().toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"});let correct=0,weighted=0,guessed=0,unsure=0;const by={};
 quiz.forEach(function(item,i){const ok=tuQuizSession.answers[i]===item.ans,conf=tuQuizSession.confidence[i]||"confident",w=ok?confidenceWeight(conf):0;if(ok)correct++;weighted+=w;if(conf==="guessed")guessed++;if(conf==="unsure")unsure++;if(!by[item.topic])by[item.topic]={c:0,t:0,w:0,guess:0,unsure:0,allConfidentCorrect:true};const b=by[item.topic];b.t++;if(ok)b.c++;b.w+=w;if(conf==="guessed")b.guess++;if(conf==="unsure")b.unsure++;if(!ok||conf!=="confident")b.allConfidentCorrect=false});
 Object.entries(by).forEach(function(entry){const topic=entry[0],v=entry[1],raw=Math.round(v.c/v.t*100),adj=Math.round(v.w/v.t*100),idx=state.topics.findIndex(function(t){return t.topic===topic}),old=state.quizTopicStats[topic]||{attempts:0,bestAdjusted:0,masteryPasses:0};let masteryPasses=old.masteryPasses||0;if(tuQuizMode==="mastery"&&v.allConfidentCorrect)masteryPasses++;if(idx>=0){state.accuracy[idx]=adj;state.lastReview[idx]=date;const prev=state.topics[idx].status;if(adj<60)state.topics[idx].status="Learning";else if(adj<80)state.topics[idx].status="Learned · Not Reviewed";else if(tuQuizMode==="mastery"&&masteryPasses>=2&&(prev==="Reviewed & Practiced"||prev==="Mastered"))state.topics[idx].status="Mastered";else state.topics[idx].status="Reviewed & Practiced"}state.quizTopicStats[topic]={attempts:(old.attempts||0)+1,bestAdjusted:Math.max(old.bestAdjusted||0,adj),latestAdjusted:adj,latestRaw:raw,last:date,mode:tuQuizMode,part:tuQuizPart,lectureId:tuQuizLecture,guessed:v.guess,unsure:v.unsure,masteryPasses:masteryPasses}});
 const rawPct=Math.round(correct/quiz.length*100),adjPct=Math.round(weighted/quiz.length*100);
 state.quizHistory.unshift({name:meta.label,pages:"TU101 "+data.lectureLabel,lectureId:tuQuizLecture,bankVersion:data.bankVersion,partId:tuQuizPart,mode:tuQuizMode,date:date,score:correct,total:quiz.length,percent:rawPct,adjustedPercent:adjPct,guessed:guessed,unsure:unsure,answers:tuQuizSession.answers.slice(),confidence:tuQuizSession.confidence.slice(),optionOrders:tuQuizSession.optionOrders.map(function(x){return x.slice()}),questionSnapshot:quiz.map(function(item){return{q:item.q,opts:item.opts.slice(),ans:item.ans,topic:item.topic,why:item.why}})});
 state.quizHistory=state.quizHistory.slice(0,200);persist();appendDevActivity("Quiz submitted",data.lectureLabel+" • "+meta.label+" • "+tuQuizMode+" • raw "+rawPct+"% • learning "+adjPct+"%",activeUser);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuQuizSession.submitted=true;renderTracker();renderHistory();renderNotesHub();renderTu101QuizLayer();
}
function tuRenderQuizResult(layer){
 const data=tuCurrentQuizData(),quiz=tuQuizBank(tuQuizMode,tuQuizPart),meta=data.parts[tuQuizPart],area=layer.querySelector("#tuQuizArea"),h=(state.quizHistory||[]).find(function(x){return x.bankVersion===data.bankVersion&&x.partId===tuQuizPart&&(x.mode||"review")===tuQuizMode});
 if(!h){tuQuizSession.submitted=false;tuRenderQuizQuestion(layer);return}
 const topicRows=[...new Set(quiz.map(function(x){return x.topic}))].map(function(topic){const st=state.quizTopicStats[topic],idx=state.topics.findIndex(function(t){return t.topic===topic});return '<div class="topic-score"><b>'+esc(topic)+'</b><span>'+(st&&st.latestRaw!=null?st.latestRaw:"—")+'% raw</span><span>'+(st&&st.latestAdjusted!=null?st.latestAdjusted:"—")+'% learn</span><span class="small">'+(idx>=0?esc(state.topics[idx].status):"—")+'</span></div>'}).join("");
 area.innerHTML='<div class="result-head"><div class="result-box"><span class="small">Raw score</span><b>'+h.score+'/'+h.total+'</b></div><div class="result-box"><span class="small">Raw accuracy</span><b>'+h.percent+'%</b></div><div class="result-box"><span class="small">Learning score</span><b>'+h.adjustedPercent+'%</b></div><div class="result-box"><span class="small">Flagged</span><b>'+((h.guessed||0)+(h.unsure||0))+'</b><span class="small">'+(h.guessed||0)+' guessed • '+(h.unsure||0)+' unsure</span></div></div>'+
 '<div class="notice"><b>'+esc(data.lectureLabel)+' • '+esc(meta.label)+'</b><br>Correct + confident = full evidence, correct + Not sure = 70%, correct + Guessed = 40%, wrong = 0. Reviewing does not award Mastered.</div>'+
 '<div class="card" style="box-shadow:none;margin-top:14px"><div class="lecture-title">Topic results</div>'+topicRows+'</div>'+
 '<div class="card" style="box-shadow:none;margin-top:14px"><div class="lecture-title">Review answers</div>'+quiz.map(function(item,i){const chosen=h.answers[i],ok=chosen===item.ans,conf=h.confidence&&h.confidence[i]||"confident",order=h.optionOrders&&h.optionOrders[i]||[0,1,2,3],chosenPos=order.indexOf(chosen),correctPos=order.indexOf(item.ans);return '<div class="review-item"><div><b>'+(i+1)+'. '+esc(item.q)+'</b> <span class="tag">'+esc(item.topic)+'</span> <span class="tag">'+(conf==="guessed"?"Guessed":conf==="unsure"?"Not sure":"Confident")+'</span></div><div class="'+(ok?"correct":"wrong")+'" style="padding:8px 10px;border-radius:9px;margin-top:8px">Your answer: '+String.fromCharCode(65+Math.max(0,chosenPos))+'. '+esc(item.opts[chosen])+' '+(ok?"✓":"✗")+'</div>'+(ok?"":'<div class="correct" style="padding:8px 10px;border-radius:9px;margin-top:6px">Correct: '+String.fromCharCode(65+Math.max(0,correctPos))+'. '+esc(item.opts[item.ans])+'</div>')+'<div class="explain">'+esc(item.why)+(ok&&conf!=="confident"?" <b>Correct but flagged, so it receives less mastery weight.</b>":"")+'</div>'+(tuQuestionNote(item,tuQuizPart)?'<div class="note-review"><b>Your saved note:</b><div>'+esc(tuQuestionNote(item,tuQuizPart)).replace(/\n/g,"<br>")+'</div></div>':"")+'</div>'}).join("")+'</div>'+
 '<div class="qnav"><button class="secondary" id="tuResultSummary">Read '+esc(data.lectureLabel)+' Summary</button><button id="tuRetake">Retake this part</button></div>';
 const rs=area.querySelector("#tuResultSummary");if(rs)rs.onclick=function(){tuSummaryLecture=tuQuizLecture;location.href=APP_BASE+"/tu101/summary/#summary-"+meta.summaries[0]};
 const retake=area.querySelector("#tuRetake");if(retake)retake.onclick=function(){tuQuizSession=tuFreshQuizSession(tuQuizMode,tuQuizPart);tuClearQuizDraft(tuQuizMode,tuQuizPart);tuSaveQuizDraft();renderTu101QuizLayer()};
}
function tuLectureQuizCompletion(meta){
 const ids=new Set((state.quizHistory||[]).filter(function(h){return h.bankVersion===meta.bankVersion&&h.partId&&!(String(h.partId).endsWith("-all"))&&h.partId!=="tu1-all"}).map(function(h){return h.partId}));
 return ids.size;
}
renderTu101QuizLayer=function(){
 let layer=document.getElementById("tu101QuizLayer");if(!layer){layer=document.createElement("div");layer.id="tu101QuizLayer";document.getElementById("quiz").appendChild(layer)}
 const data=tuLectureData(tuQuizLecture);if(!data){setTuQuizLecture(tuQuizLecture);return}
 if(!data.parts[tuQuizPart])tuQuizPart=tuLectureRegularParts(data)[0]||data.cumulativeId;
 if(!tuQuizSession||tuQuizSession.lectureId!==tuQuizLecture||tuQuizSession.part!==tuQuizPart||tuQuizSession.mode!==tuQuizMode)tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);
 layer.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Practice • Midterm Lectures 1–6</div><h2>TU101 Quiz Library</h2><p>Each lecture has 4 focused parts plus a 40-question cumulative in both Reviewing and Mastering. New lecture modules load only when selected.</p></div></div>'+
 tuLectureSelectorMarkup(tuQuizLecture,"quiz")+
 '<div class="card quiz-shell"><div class="quiz-library"><div class="lecture-title">✅ '+esc(data.lectureLabel)+' — '+esc(data.title)+'</div><div class="small">'+esc(data.source)+' • 40 Reviewing + 40 Mastering questions.</div><div class="quiz-set-progress" id="tuLectureQuizProgress">0/4 parts done</div></div>'+
 '<div id="tuPartPicker" class="part-picker"></div><div class="practice-dot-legend"><span><i class="practice-dot not-started"></i> not started</span><span><i class="practice-dot red"></i> guessed</span><span><i class="practice-dot orange"></i> needs work</span><span><i class="practice-dot yellow"></i> practiced</span><span><i class="practice-dot green"></i> strong</span><span style="margin-left:auto">R = Reviewing • M = Mastering</span></div>'+
 '<div class="mode-switch"><button class="mode-btn '+(tuQuizMode==="review"?"active":"")+'" data-tu-mode="review"><b>Reviewing — recommended first</b><span class="small">Clear recall + application • does not award Mastered</span></button><button class="mode-btn '+(tuQuizMode==="mastery"?"active":"")+'" data-tu-mode="mastery"><b>Mastering — harder</b><span class="small">Close distractors • source comparison • multi-step reasoning</span></button></div>'+
 '<div id="tuQuizReadingGuide" class="read-with"></div><div id="tuResumeNotice"></div><div id="tuQuizArea"></div></div>';
 layer.querySelectorAll("[data-tu-quiz-lecture]").forEach(function(b){b.onclick=function(){setTuQuizLecture(b.dataset.tuQuizLecture)}});
 layer.querySelectorAll("[data-tu-mode]").forEach(function(b){b.onclick=function(){tuSetQuizMode(b.dataset.tuMode)}});
 tuRenderQuizPicker(layer);tuRenderReadingGuide(layer);tuRenderQuizQuestion(layer);
};

const v1316NotesBase=getAllSavedNotes;
getAllSavedNotes=function(){
 if(activeSubject!=="tu101")return v1316NotesBase();
 const items=[],loaded=Object.keys(TU101_LECTURE_META).map(tuLectureData).filter(Boolean);
 Object.entries(state.notes||{}).forEach(function(entry){const idx=entry[0],val=entry[1],media=getNoteMedia("progress",idx);if(!String(val||"").trim()&&!media.length)return;const t=state.topics[Number(idx)];items.push({kind:"progress",lecture:t&&t.lecture||"Other",title:t&&t.topic||("Progress topic #"+idx),meta:"Progress topic note",value:String(val),key:String(idx),sort:1})});
 const partLookup={};loaded.forEach(function(d){Object.keys(d.parts||{}).forEach(function(id){partLookup[id]={data:d,meta:d.parts[id]}})});
 Object.entries(state.quizNotes&&state.quizNotes.sections||{}).forEach(function(entry){const part=entry[0],val=entry[1];if(!String(val||"").trim()&&!getNoteMedia("section",part).length)return;const hit=partLookup[part];items.push({kind:"section",lecture:hit?hit.data.lectureLabel:"Other",title:hit?hit.meta.label:part,meta:(hit?hit.meta.source+" • ":"")+"Quiz section note",value:String(val),key:part,sort:2})});
 const known=new Set();loaded.forEach(function(d){Object.keys(d.parts||{}).forEach(function(part){["review","mastery"].forEach(function(mode){const bank=mode==="mastery"?d.mastery:d.review;let qs;if(part===d.cumulativeId)qs=tuLectureRegularParts(d).flatMap(function(id){return bank[id]||[]});else qs=bank[part]||[];qs.forEach(function(item){const key=questionNoteKey(item,part),val=state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[key];if((!String(val||"").trim()&&!getNoteMedia("question",key).length)||known.has(key))return;known.add(key);items.push({kind:"question",lecture:d.lectureLabel,title:item.q,meta:d.parts[part].label+" • "+(mode==="review"?"Reviewing":"Mastering")+" • "+item.topic,value:String(val),key:key,partId:part,question:item,sort:3})})})})});
 Object.entries(state.quizNotes&&state.quizNotes.questions||{}).forEach(function(entry){const key=entry[0],val=entry[1];if(String(key).startsWith("flashcard::"))return;if((!String(val||"").trim()&&!getNoteMedia("question",key).length)||known.has(key))return;items.push({kind:"question-orphan",lecture:"TU101",title:"Saved quiz question note",meta:"Archived TU101 question",value:String(val),key:key,sort:4})});
 const flashSeen=new Set();normalizedFlashcardDecks("tu101").filter(function(deck){return!deck.cumulative}).forEach(function(deck){deck.cards.forEach(function(card){if(flashSeen.has(card.id))return;flashSeen.add(card.id);const key=flashcardNoteKey("tu101",card.id),val=state.quizNotes&&state.quizNotes.questions&&state.quizNotes.questions[key];if(!String(val||"").trim()&&!getNoteMedia("question",key).length)return;items.push({kind:"question",lecture:deck.lectureLabel||"TU101",title:card.front,meta:deck.label+" • Flashcard • Answer: "+card.back,value:String(val||""),key:key,sort:5})})});
 return items;
};

const v1316RouteBase=applyPathRoute;
applyPathRoute=async function(){
 const p=location.pathname.replace(/\/+$/,"");
 if(activeSubject==="tu101"&&p.endsWith("/flashcards")){await ensureAllTu101ModulesLoaded();ensureFlashcardWorkspace();switchTab("flashcards");renderFlashcards();return}
 if(activeSubject==="tu101"&&p.endsWith("/notes")){await ensureAllTu101ModulesLoaded();switchTab("notes");renderNotesHub();return}
 if(activeSubject==="tu101"&&p.endsWith("/summary")){
   const hm=String(location.hash||"").match(/^#summary-tu([1-6])s/),id=hm?("l"+hm[1]):tuSummaryLecture;
   await ensureTuLectureLoaded(id);tuSummaryLecture=id;switchTab("summary");renderTu101Summary();
   if(location.hash)setTimeout(function(){const el=document.querySelector(location.hash);if(el)el.scrollIntoView({block:"start"})},100);
   return;
 }
 if(activeSubject==="tu101"&&p.endsWith("/quiz")){
   const hm=String(location.hash||"").match(/^#lecture-l([1-6])$/),id=hm?("l"+hm[1]):tuQuizLecture;
   await ensureTuLectureLoaded(id);tuQuizLecture=id;const data=tuCurrentQuizData();if(!data.parts[tuQuizPart])tuQuizPart=tuLectureRegularParts(data)[0]||data.cumulativeId;tuQuizSession=tuLoadQuizDraft(tuQuizMode,tuQuizPart);switchTab("quiz");renderTu101QuizLayer();return;
 }
 return v1316RouteBase();
};
const v1316SwitchTabBase=switchTab;
switchTab=function(tab){
 const out=v1316SwitchTabBase(tab);
 if(activeSubject==="tu101"&&tab==="flashcards")ensureAllTu101ModulesLoaded().then(function(){renderFlashcards()}).catch(function(){});
 if(activeSubject==="tu101"&&tab==="notes")ensureAllTu101ModulesLoaded().then(function(){renderNotesHub()}).catch(function(){});
 return out;
};
const v1316PreviewBase=flashcardPreviewMarkup;
flashcardPreviewMarkup=function(subjectId){
 if(subjectId!=="tu101")return v1316PreviewBase(subjectId);
 return '<section class="panel active"><div class="panel-intro"><div><div class="eyebrow">Active Recall</div><h2>TU101 Flashcards</h2><p>Midterm Lectures 1–6 each have focused part decks plus a Full Lecture deck. Modules load on demand in the real workspace.</p></div></div><div class="card"><div class="lecture-title">Lecture-wide completion</div><p class="small">Reach 100% on a Full Lecture deck after clearing all missed-card retries to finish that lecture.</p></div></section>';
};
